import argparse
import os
from pathlib import Path
from urllib.parse import quote

import httpx

from schemas import Review


def render_review(review: Review) -> str:
    sections = [
        "## AI code review",
        "_Generated by an LLM; findings require human verification._",
        review.summary,
    ]

    for finding in review.findings:
        sections.extend([
            f"### {finding.severity.upper()} — `{finding.file}`",
            finding.explanation,
            f"**Suggested fix:**\n\n{finding.suggestion}",
        ])

    if not review.findings:
        sections.append("No concrete findings reported.")

    sections.append("### Suggested tests")
    sections.extend(f"- {test}" for test in review.suggested_tests)

    return "\n\n".join(sections)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--post", action="store_true")
    args = parser.parse_args()

    review = Review.model_validate_json(
        Path("reports/review.json").read_text(encoding="utf-8")
    )
    body = render_review(review)

    print("Target: RETCx/gitlab-ai-reviewer, MR !1\n")
    print(body)

    if not args.post:
        print("\nPreview only. Add --post to publish this review.")
        return

    token = os.environ.get("GITLAB_TOKEN", "").strip()
    if not token:
        raise SystemExit("Please set GITLAB_TOKEN first.")

    project = quote("RETCx/gitlab-ai-reviewer", safe="")
    url = (
        f"https://gitlab.com/api/v4/projects/{project}"
        "/merge_requests/1/notes"
    )

    response = httpx.post(
        url,
        headers={"PRIVATE-TOKEN": token},
        json={"body": body},
        timeout=20,
    )
    response.raise_for_status()

    print(f"\nPosted successfully. Note ID: {response.json()['id']}")


if __name__ == "__main__":
    main()